"""Native core inventory/spawn capabilities; lifecycle activation belongs to installed LayerRuntime."""
import ast
from pathlib import Path
root=Path(__file__).resolve().parents[1]
tree=ast.parse((root/'tools/generate-layer-families.py').read_text(encoding='utf-8'))
guard=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='guard' for t in n.targets))
text='''package fpv.construction;
// Generated by tools/generate-layer-cores.py.
import arc.math.geom.Geometry;
import mindustry.gen.*;
import mindustry.game.Team;
import mindustry.world.*;
import mindustry.world.blocks.storage.CoreBlock;

/** No team registry, shared-item aliasing or packed-XY spawn calls during create/decode. */
final class LayerCoreFamilies {
    static boolean supports(Class<?> type){return type==CoreBlock.CoreBuild.class;}
    static Building create(LayerBuildingAdapter owner,Block block,Class<?> type){
        return ((CoreBlock)block).new CoreBuild(){
'''
text+='\n'.join('            '+line for line in guard.strip().splitlines())
text+='''
            @Override public void created(){storageCapacity=block.itemCapacity;}
            @Override public void placed(){}
            @Override public void onProximityUpdate(){}
            @Override public void onRemoved(){}
            @Override public void requestSpawn(Player player){owner.requestCoreSpawn(this,player);}
        };
    }
}
'''
(root/'src/main/java/fpv/construction/LayerCoreFamilies.java').write_text(text,encoding='utf-8')
print('Generated isolated core family')
